import { EntryBook } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const book = new EntryBook();
equal(book.current(), null, 'new book has no selection');
equal(book.move(3), null, 'move on empty book returns null');
equal(book.remove('missing'), false, 'remove unknown ID returns false');
equal(book.select('missing'), false, 'select unknown ID returns false');
expectRange(() => book.add({ id: '   ', weight: 1 }), 'blank ID is rejected');
expectRange(() => book.add({ id: 'x', weight: Infinity }), 'infinite weight is rejected');
expectRange(() => book.add({ id: 'x', weight: NaN }), 'NaN weight is rejected');
expectRange(() => book.move(0.5), 'fractional move is rejected');
expectRange(() => book.move(Infinity), 'infinite move is rejected');

const original = { id: 'a', weight: 1 };
book.add(original);
book.add({ id: 'b', weight: 2 });
book.add({ id: 'c', weight: 3 });
original.weight = 99;
deepEqual(book.list(), [{ id: 'a', weight: 1 }, { id: 'b', weight: 2 }, { id: 'c', weight: 3 }], 'add copies entries and preserves insertion order');

equal(book.select('b'), true, 'known ID can be selected');
book.add({ id: 'b', weight: 20 });
deepEqual(book.list(), [{ id: 'a', weight: 1 }, { id: 'b', weight: 20 }, { id: 'c', weight: 3 }], 'replacement retains its position');
deepEqual(book.current(), { id: 'b', weight: 20 }, 'replacement retains selection');
deepEqual(book.move(1), { id: 'c', weight: 3 }, 'positive movement advances selection');
deepEqual(book.move(1), { id: 'a', weight: 1 }, 'movement wraps forward');
deepEqual(book.move(-1), { id: 'c', weight: 3 }, 'movement wraps backward');

const currentCopy = book.current() as { id: string; weight: number };
currentCopy.weight = -1;
const listCopy = book.list() as Array<{ id: string; weight: number }>;
listCopy[0].weight = -2;
listCopy.push({ id: 'extra', weight: 0 });
deepEqual(book.current(), { id: 'c', weight: 3 }, 'current returns a fresh entry');
deepEqual(book.list(), [{ id: 'a', weight: 1 }, { id: 'b', weight: 20 }, { id: 'c', weight: 3 }], 'list returns a fresh array and entries');

equal(book.remove('c'), true, 'selected entry can be removed');
deepEqual(book.current(), { id: 'a', weight: 1 }, 'removing selected last entry wraps to first');
book.select('a');
equal(book.remove('a'), true, 'selected first entry can be removed');
deepEqual(book.current(), { id: 'b', weight: 20 }, 'entry occupying removed index becomes selected');
equal(book.remove('b'), true, 'last entry can be removed');
equal(book.current(), null, 'empty book has no selection');

function unselectedBook(): EntryBook {
  const result = new EntryBook();
  result.add({ id: 'a', weight: 1 });
  result.add({ id: 'b', weight: 2 });
  result.add({ id: 'c', weight: 3 });
  return result;
}
deepEqual(unselectedBook().move(0), { id: 'a', weight: 1 }, 'zero starts at first when unselected');
deepEqual(unselectedBook().move(1), { id: 'b', weight: 2 }, 'positive offset counts forward from first when unselected');
deepEqual(unselectedBook().move(-1), { id: 'c', weight: 3 }, 'negative offset counts backward from first when unselected');

